package com.example.Hospital.Management.System.services; import com.example.Hospital.Management.System.entities.*; import com.example.Hospital.Management.System.dtos.*; import com.example.Hospital.Management.System.repositories.*; import com.example.Hospital.Management.System.exceptions.*; import org.springframework.stereotype.Service; import java.util.*; @Service public class GuardianService{private final GuardianRepository r;private final PatientRepository pr;public GuardianService(GuardianRepository r,PatientRepository pr){this.r=r;this.pr=pr;} private Guardian find(Long id){return r.findById(id).filter(BaseClass::getIsActive).orElseThrow(()->new ResourceNotFoundException("Guardian not found"));} private GuardianDTO dto(Guardian e){return GuardianDTO.builder().id(e.getId()).name(e.getName()).relationship(e.getRelationship()).phoneNumber(e.getPhoneNumber()).patientId(e.getPatient().getId()).build();} private void apply(Guardian e,GuardianDTO d){Patient p=pr.findById(d.getPatientId()).filter(BaseClass::getIsActive).orElseThrow(()->new ResourceNotFoundException("Patient not found"));e.setName(d.getName());e.setRelationship(d.getRelationship());e.setPhoneNumber(d.getPhoneNumber());e.setPatient(p);} public GuardianDTO create(GuardianDTO d){Guardian e=new Guardian();apply(e,d);return dto(r.save(e));} public List<GuardianDTO> all(){return r.findByIsActiveTrue().stream().map(this::dto).toList();} public GuardianDTO get(Long id){return dto(find(id));} public GuardianDTO update(Long id,GuardianDTO d){Guardian e=find(id);apply(e,d);return dto(r.save(e));} public void delete(Long id){Guardian e=find(id);e.setIsActive(false);r.save(e);}}
